#!/bin/sh
config_files_menu(){ while :; do c=$(ui_menu 'Configuration files' 'Each supported file includes a TUI option wizard, raw editor, defaults, viewing, backup, and managed-block removal.' profile '.profile login environment' bashrc '.bashrc Bash behavior' zshrc '.zshrc Zsh behavior' ashrc '.ashrc Ash behavior' nanorc '.nanorc Nano editor' vimrc '.vimrc Vim editor' inputrc '.inputrc Readline behavior' gitconfig '.gitconfig Git defaults' tmux '.tmux.conf terminal multiplexer' sshclient '.ssh/config SSH client' starship '.config/starship.toml prompt' nvim 'Neovim init.lua (raw/template)' micro 'Micro settings.json (raw/template)' helix 'Helix config.toml (raw/template)' system 'Browse common /etc files') || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in profile) config_target_menu Profile "$CURRENT_HOME/.profile" profile_wizard profile;; bashrc) config_target_menu Bash "$CURRENT_HOME/.bashrc" bash_wizard bashrc;; zshrc) config_target_menu Zsh "$CURRENT_HOME/.zshrc" zsh_wizard zshrc;; ashrc) config_target_menu Ash "$CURRENT_HOME/.ashrc" ash_wizard ashrc;; nanorc) config_target_menu Nano "$CURRENT_HOME/.nanorc" nano_wizard nanorc;; vimrc) config_target_menu Vim "$CURRENT_HOME/.vimrc" vim_wizard vimrc;; inputrc) config_target_menu Readline "$CURRENT_HOME/.inputrc" inputrc_wizard inputrc;; gitconfig) config_target_menu Git "$CURRENT_HOME/.gitconfig" git_wizard gitconfig;; tmux) config_target_menu Tmux "$CURRENT_HOME/.tmux.conf" tmux_wizard tmux;; sshclient) mkdir -p "$CURRENT_HOME/.ssh"; config_target_menu 'SSH client' "$CURRENT_HOME/.ssh/config" ssh_client_wizard ssh_config; chmod 700 "$CURRENT_HOME/.ssh" 2>/dev/null; chmod 600 "$CURRENT_HOME/.ssh/config" 2>/dev/null;; starship) mkdir -p "$CURRENT_HOME/.config"; config_target_menu Starship "$CURRENT_HOME/.config/starship.toml" starship_wizard starship;; nvim) mkdir -p "$CURRENT_HOME/.config/nvim"; ensure_template nvim.lua "$CURRENT_HOME/.config/nvim/init.lua";; micro) mkdir -p "$CURRENT_HOME/.config/micro"; ensure_template micro.json "$CURRENT_HOME/.config/micro/settings.json";; helix) mkdir -p "$CURRENT_HOME/.config/helix"; ensure_template helix.toml "$CURRENT_HOME/.config/helix/config.toml";; system) system_files_menu;; esac; done; }
ensure_template(){ n=$1; f=$2; [ -e "$f" ] || cp "$ISH_AOK_CONFIG_ROOT/templates/$n" "$f" 2>/dev/null || write_file "$f" 644 ''; edit_file "$f"; }
system_files_menu(){ while :; do c=$(ui_menu '/etc files' 'Editing system files requires care. Existing files are backed up before editing.' hosts hosts resolv 'resolv.conf' hostname hostname profile profile environment environment shells shells fstab fstab issue issue motd motd services services nsswitch nsswitch.conf login 'login.defs') || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; edit_file "/etc/$c"; done; }
